def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Select solution based on dominance and weight balance
    scores = []
    for sol, obj in archive:
        total_weight = np.sum(weight_lst * sol)
        score = (obj[0] + obj[1]) / (total_weight + 1e-6)
        scores.append(score)

    selected_idx = np.argmax(scores)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Hybrid local search with strategic additions/removals
    n_items = len(weight_lst)
    current_weight = np.sum(weight_lst * new_solution)

    # Calculate value-weight tradeoff for both objectives
    tradeoff1 = value1_lst / (weight_lst + 1e-6)
    tradeoff2 = value2_lst / (weight_lst + 1e-6)
    combined_tradeoff = tradeoff1 + tradeoff2
    sorted_indices = np.argsort(-combined_tradeoff)

    # Perform strategic operations based on combined tradeoff
    for i in sorted_indices[:min(20, n_items)]:
        if random.random() < 0.7:  # Higher probability for better items
            if new_solution[i] == 1:
                new_weight = current_weight - weight_lst[i]
                if new_weight <= capacity:
                    new_solution[i] = 0
                    current_weight = new_weight
            else:
                new_weight = current_weight + weight_lst[i]
                if new_weight <= capacity:
                    new_solution[i] = 1
                    current_weight = new_weight

    # Additional probabilistic swap with diversity consideration
    if n_items >= 3:
        i, j, k = random.sample(range(n_items), 3)
        if random.random() < 0.5:  # Higher probability for triple operations
            # Try to find a better triple operation
            best_op = None
            best_value = -1

            # Evaluate possible operations
            ops = [
                (i, j), (i, k), (j, k),
                (i,), (j,), (k,)
            ]

            for op in ops:
                if len(op) == 2:
                    a, b = op
                    if new_solution[a] != new_solution[b]:
                        if new_solution[a] == 1:
                            new_weight = current_weight - weight_lst[a] + weight_lst[b]
                            if new_weight <= capacity:
                                val = (value1_lst[a] + value1_lst[b]) + (value2_lst[a] + value2_lst[b])
                                if val > best_value:
                                    best_value = val
                                    best_op = op
                        else:
                            new_weight = current_weight + weight_lst[a] - weight_lst[b]
                            if new_weight <= capacity:
                                val = (value1_lst[a] + value1_lst[b]) + (value2_lst[a] + value2_lst[b])
                                if val > best_value:
                                    best_value = val
                                    best_op = op
                else:
                    x = op[0]
                    if new_solution[x] == 1:
                        new_weight = current_weight - weight_lst[x]
                        if new_weight <= capacity:
                            val = value1_lst[x] + value2_lst[x]
                            if val > best_value:
                                best_value = val
                                best_op = op
                    else:
                        new_weight = current_weight + weight_lst[x]
                        if new_weight <= capacity:
                            val = value1_lst[x] + value2_lst[x]
                            if val > best_value:
                                best_value = val
                                best_op = op

            # Apply the best operation found
            if best_op:
                if len(best_op) == 2:
                    a, b = best_op
                    new_solution[a], new_solution[b] = new_solution[b], new_solution[a]
                else:
                    x = best_op[0]
                    new_solution[x] = 1 - new_solution[x]

    return new_solution

