    diversity_scores = []
    for sol, obj in archive:
        diversity = 0
        for other_sol, other_obj in archive:
            diversity += np.sqrt((obj[0] - other_obj[0])**2 + (obj[1] - other_obj[1])**2)
        sparsity = np.mean(np.abs(sol - archive[0][0]))
